output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves face the shopper on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              {
                "not": "singleFileShelfAisle"
              },
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "singleFileShelfAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "must_park_cart_at_narrow_aisle_mouth",
    "text": "When a shopper interacts at the mouth of a single-file shelf aisle while holding a cart, the interaction should be used to park the cart.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "interactAtMouthWithCart": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        },
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "interactAtMouthWithCart",
      "discharge": "parkCartAtMouth"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at a single-file aisle mouth, the shopper is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "return_to_cart_bay_after_single_file_shopping",
    "text": "After interacting with a shelf from inside a single-file aisle, the shopper must return to a cart bay at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfInteraction",
      "discharge": "cartBay"
    }
  },
  {
    "id": "no_cart_shelf_interaction_in_single_file_aisle",
    "text": "A shopper may not interact with shelves in a single-file aisle while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cart_drop_only_at_cart_bays",
    "text": "Carts may be set down only at designated wide cart bays at the mouths of the narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartBay"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west",
    "text": "Store traffic follows a one-way circulation rule, so shoppers must not move west.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
